    "全部": "全部提示",
    "舞台の画面で左右キーを押したとき、セリフキューだけを移る。タイムライン右端の対象を選んだ場合は、そちらの選択が優先されます": "在舞台画面按左右方向键时，只在台词提示之间跳转。若在时间轴右端选择了目标，则优先使用该选择",
    "選択してDeleteで削除": "选择后按Delete删除",
    "演者がショーの動きを確認するためのViewerのリンクです。": "这是供演员确认演出走位的Viewer链接。",
