    "ドラッグで幅を変更。左右キーで調整、ダブルクリックまたはEnterで元に戻す": "拖动调整宽度。用左右方向键微调，双击或按Enter恢复默认",
    "ドラッグで高さを変更。上下キーで調整、ダブルクリックまたはEnterで元に戻す": "拖动调整高度。用上下方向键微调，双击或按Enter恢复默认",
    "演者の一覧の高さ": "演员列表高度",
    "大道具の一覧の高さ": "布景装置列表高度",
    "大道具の一覧の高さ": "布景装置列表高度",
