    "劇場設定の未適用の編集は破棄されます。作りかけのショーは一覧に残します。前のショーへ戻りますか？": "剧场设置中尚未应用的编辑将被丢弃。未完成的演出会保留在列表中。要返回上一个演出吗？",
    "劇場設定の未適用の編集は破棄されます。いまのショーは一覧に残します。別のショーを開きますか？": "剧场设置中尚未应用的编辑将被丢弃。当前演出会保留在列表中。要打开其他演出吗？",
    "劇場の寸法が変わると、現在の照明が動かなくなる可能性があります。変更後に各シーンの照明を点検してください。寸法を変更しますか？": "剧场尺寸改变后，当前照明可能无法正常工作。更改后请检查每个场景的照明。要更改尺寸吗？",
