    "転換中に演者を歩かせる": "换场时让演员走动",
    "ONでは演者の移動・入り・はけを歩いて表示します。OFFでは演者が次のシーンの配置へすぐ切り替わります。大道具・照明・暗転の転換は続きます": "开启时，演员移动、进场和退场会以步行呈现。关闭时，演员会立即切换到下一场景的位置。布景、灯光和暗场换场仍会继续。",
