    "楽器に合わせて自動": "根据乐器自动调整",
    "照明デザインの平面図で灯体の淡い白枠を表示します。OFFでも選択中の金色の枠と、正面図・側面図・3Dの表示は残ります": "在灯光设计平面图中显示灯具的浅色轮廓。关闭后仍保留选中灯具的金色轮廓，正面图、侧面图和3D视图不受影响。",
    "選択中のシーンの上下に、転換の長さ・暗転・メモを表示する。OFFでも内容は消えません": "在所选场景的上下显示换场时长、暗场和备注。关闭后内容不会被删除",
    "選択中のシーンの上下に、次のシーンへの移動時間・暗転・メモを表示する。OFFでも内容は消えません": "在所选场景的上下显示前往下一场景的移动时间、暗场和备注。关闭后内容不会被删除",
