    "この客席範囲を選択しました。ドラッグで動かせます。": "已选择此观众席范围。可拖动移动。",
    "この客席範囲を選択しました。辺のタップで範囲を追加・解除できます。": "已选择此观众席范围。点按舞台的边可添加或取消范围。",
    "この客席範囲を選択しました。": "已选择此观众席范围。",
    "四角の追加ステージを選択しました。ドラッグで動かせます。": "已选择矩形的追加舞台。可拖动移动。",
    "丸の追加ステージを選択しました。ドラッグで動かせます。": "已选择圆形的追加舞台。可拖动移动。",
    "合成済みの追加ステージは一体の舞台面です。戻すと合成前にできます。": "已合并的追加舞台是一个整体的舞台面。撤销即可恢复合并前的状态。",
    "バックスクリーンを選択しました。左の長さ欄または端点で調整できます。": "已选择背景屏。可用左侧的长度栏或拖动端点调整。",
