    venueNote: {
      proscenium: "观众席在一侧。镜框把舞台和观众席分开，背景和布景举足轻重。",
      thrust: "舞台伸入观众席，三面被围。总有人看到你的背面。",
      arena: "观众席环绕整个表演区。没有正面，得从每个角度都成立。",
      outdoor: "没有围合的观众席。前排围栏和到调音台的距离决定尺度。",
      blackbox: "一个每次都重新决定观众席位置的方盒子。形式本身就是变量。",
      "theatre-tram": "世田谷公共剧场位于三轩茶屋的实验剧场。下沉式尽端舞台：没有镜框，舞台与观众席同处一个盒子。平面呈T形——8.4米的后区盒体收窄后，展开为14.7米的主空间。一台升降台（5.44×2.72米）位于台口附近的中央；基本形态225席。",
      "arena-concert": "暂定尺寸（未对照图纸）。并非实际场馆。",
      "dome-concert": "暂定尺寸（未对照图纸）。并非实际场馆。",
      "festival-field": "暂定尺寸（未对照图纸）。并非实际场馆。",
      "end-stage": "没有镜框，舞台与观众席同处一个盒子。观众在一侧，靠阶梯地面取得高度。既无侧台也无镜框来遮挡机构，因此要先决定不想被看到的东西放在哪里。尺寸为暂定值。",
      "gym-stage": "体育馆一端的浅舞台。台口宽但进深仅约6米，无法吊挂。观众席是平地，后排看不到脚下。舞台高约1.1米，多数没有侧台。尺寸为暂定值，未找到统一规格。",
      "banquet-hall": "在宴会厅搭临时舞台。舞台约8×4米，天花约4米，无法吊挂，向上抛掷的节目由天花决定。观众围圆桌或站立，没有作为围合的观众席。柱子、入口以及吊灯下方的留空决定构图。尺寸为暂定值。",
      "hall-shoebox": "观众席呈矩形排列，中央区两侧各有一条通道——日本公共剧场最常见的划分方式。从两侧区看，舞台是斜的。通道上没有座位，因此无人从那里观看。尺寸与划分均为暂定值。",
      "hall-fan": "台口前缘向观众席画出弧线，观众席呈扇形展开——日本公共剧场最常见的形状。中央区两侧各有一条通道，两侧区比舞台更宽。弧线让站在中央的演员离观众更近；从两侧区看，舞台是斜的。进深含弧线顶点。尺寸与划分均为暂定值。",
      "in-the-round": "观众席从四周完整围住表演区。与马戏大棚不同，座席为单层，表演圆也更小。没有正面，站位与朝向必须从每个角度都成立。四个区之间的缺口就是出入口，登场即穿过观众席。尺寸为暂定值。",
      "arena-show": "在体育馆的演出。舞台设在一端，观众席由三面固定看台与铺在地面的临时座席组成。加上伸展台，地面座席就被分成左右两块：演员能走到观众中间，但也会被两侧同时看到。地面座席每场重搭，因此这只是常见的一种布局，并非标准。尺寸为暂定值。",
      "dome-show": "在穹顶场馆的演出。器形是圆的，观众席绕行一周，舞台后方的座位有时也会出售。伸展台布局把舞台设在一端并伸入观众席；中央舞台布局则在正中搭圆形舞台，面向四周。两者的地面座席都每场重搭。这只是常见的一种布局，并非标准。尺寸为暂定值。",
      "kabuki-stage": "歌舞伎的舞台。歌舞伎座公布台口91尺（约27.6米）、高21尺（约6.4米），舞台中央嵌有直径60尺（约18.2米）的旋转舞台。花道自下手（观众席左侧）贯穿观众席伸出，长60尺（约18.2米）、宽约1.5米，与舞台同高，演员就这样走着上下场。花道的“七三”（距舞台三分、距扬幕七分）设有“すっぽん”升降口，人物由此升出。花道把观众席分成两半，靠外侧的席位离花道很近，离舞台却很远。上手有时会加设临时的“仮花道”，但并非常设，此处不做。进深20米在歌舞伎座官方页面上没有记载，但另一份独立的行业资料（2013年舞台照明施工案例）予以确认。花道的左右位置与观众席进深仍为估值。升降台、二重舞台、定式幕与舞台高度本预设不做。",
      "noh-stage": "能乐堂的舞台。本舞台是京间三间见方（约5.9米）的近乎正方形，后方为乐师所在的后座，一侧为歌队所在的地谣座。桥挂从后方一角伸出，演员由此登场（标准为六至七间，11至13米）。舞台探入观众席，因此正面席与侧面席看到的完全不同。本预设不做屋顶、镜板上的松树与切户口。桥挂实际是斜向搭设，此处按直角处理。",
      traverse: "细长的表演带，两侧被观众席夹住。没有正面：面向一侧就等于把背留给另一侧，因此靠朝向与移动来经营看法。两端通常是出入口。观众席只有两块，既无通道也无正面。尺寸为暂定值。",
    },
