    "text.アリーナ・ドームなど大きい会場の3Dカメラで、遠くの客席を簡単に描いて動きを軽くする。近くの見え方は変わりません", // 同項目の説明
    "text.客席の入り", "text.満席", "text.空席",   // 3Dカメラの客席の入り（満席／空席）の切り替え（2026-09-16 追加・ネイティブ確認前。上座情况／满座／空场の据わり）
    "text.フロア前方", "text.フロア後方", "text.下段中央", "text.上段中央", "text.最上段",
