    "maps.size.arena-concert-provisional", "maps.size.dome-concert-provisional", "maps.size.festival-field-provisional",
    "maps.setKind.cyrwheel",   // Cyr轮／大环——中華圏で定訳未満（既存プロンプト側と同じ懸念）
    "maps.setKind.teeter",     // 跷板／弹板／跳板のどれが通るか
