// v0.3.39 release notes.
Object.assign(window.SHOSAI_I18N_PACKS["zh-Hans"].text, {
  "全タブで現在の情報と操作の説明を見られる情報バーを追加しました。ヘッダーから表示を切り替えられます。": "新增信息栏，在所有标签页显示当前信息与操作说明。可从页首切换显示。",
  "灯体名は通常は短い番号で表示し、選択時やカーソルを合わせたときに名前を出します。機材配置と照明の欄も使いやすくしました。": "灯具平时显示简短编号，选中或光标停留时显示名称。器材配置与照明面板也更易操作。",
  "シーン操作の入口、劇場設定の入力・削除、選択中の操作欄と文字表示を改善しました。": "改善了场景操作入口、剧场设置的输入与删除、所选项目的操作面板和文字显示。",
  "シーン分割などを元に戻したとき、ほかのシーンの支持台との関連が失われる不具合を修正しました。": "修正还原场景分割等操作时，其他场景的支撑平台关联丢失的问题。",
  "Mac版に隊形の試作ページとAI用の手引きを同梱しました。保存形式は変わりません。": "Mac版现在随附队形试作页面与AI指南。保存格式不变。"
});

